/** What /v1/audio/speech takes: a song (a song model: input the lyrics, instructions the music) or speech (a speech model: input the text; voice, language, instructions, ref_audio, ref_text ...), as the model this server runs is */
export interface AudioSpeechBody {
  /** a song: the lyrics ([verse] / [chorus] tags on lines of their own; empty: instrumental); speech: the text to say (required; also as text), or a list of texts said in turn as one stream (the same voice and seed, `gap` seconds between; not with url) */
  input?: unknown | null;
  /**
   * a list of texts: the silence between them in seconds, 0-5 (0.3 by default)
   * @minimum 0.0
   * @maximum 5.0
   * @default 0.3
   */
  gap?: number | null;
  /**
   * the rate of the sound in Hz, 8000-96000 (24000 by default, OpenAI's; pcm and wav say it in X-Sample-Rate); not with url
   * @minimum 8000
   * @maximum 96000
   * @default 24000
   */
  sample_rate?: number | null;
  /** a song: true sends its wav as it is made too (speech's wav is streamed anyway) */
  stream?: boolean | null;
  /** a song: the music - genre, mood, tempo, instruments, voice (required unless a recording is given; also as prompt or description); speech: how to say it, the voice to make up, or a cloned voice's direction */
  instructions?: string | null;
  /** guidance (also as guidance_scale) */
  cfg?: number | null;
  /** a song: the lyrics' language as a code; speech: the language spoken (auto by default) */
  language?: string | null;
  /** the model's id (this server's; OpenAI's and the reference servers' names are taken for it) */
  model?: string | null;
  /** the engine's own options, {NAME: value} (/api/info lists them) */
  options?: Record<string, unknown> | null;
  /** a song: its length; speech: the most to make (also as duration, or max_new_tokens: frames) */
  seconds?: number | null;
  seed?: number | null;
  /** also as num_inference_steps */
  steps?: number | null;
  /** OpenAI's mp3, opus, aac, flac, wav or pcm, streamed as it is made (speech: mp3 by default; pcm is raw s16le, 24 kHz, mono; wav a header of unknown length, then that), or url (JSON with its link; needs an output directory); a song: wav (the default: the whole file), url, or another format streamed */
  response_format?: string | null;
  /**
   * how fast it is said, 0.25-4 (OpenAI's; beyond it clamped), over the whole answer; not with url
   * @minimum 0.25
   * @maximum 4.0
   * @default 1.0
   */
  speed?: number | null;
  /** audio (the default: the audio bytes, streamed); OpenAI's sse is refused */
  stream_format?: string | null;
  /** speech: false says the text as written (default: symbols as words, no markdown) */
  normalize?: boolean | null;
  /**
   * yue2-3b-q8: a score (ABC text) to sing over instead of one drawn (cot melody or full) - a cover's melody, or the score an earlier song came back with (its score) to sing it again with new words: the same seed and style keep the melody
   * @maxLength 200000
   */
  abc?: string | null;
  /** yue2-3b-q8: what it writes before the music - full (a melody and chords score; default), melody (a melody alone: covers), off (none; the codes guided 1.01 by default) */
  cot?: SongCot | null;
  /** acestep-1.5, a task on a recording: the recording (WAV, MP3, FLAC, Ogg, M4A as base64 or a data: URL, or upload:<name> from audio.upload); the song is as long as it (repaint: to repaint_end). yue2-3b-q8, a cover: the recording whose score (SheetSage2: its melody for cot melody - the default then -, melody and chords for full) is sung in the new style with input's words (the song's own or new ones); option score-only true: the score alone */
  audio?: string | null;
  /** acestep-1.5: the tempo (else the planner's, or none said) */
  bpm?: number | null;
  /** cover: how close the start is to the recording, 0 (from noise) to 1 (0) */
  cover_noise?: number | null;
  /** cover / repaint: the share of the steps conditioned on the recording, 0 to 1 (0.5) */
  cover_strength?: number | null;
  /** acestep-1.5: key and scale, "C major", "F# minor" */
  key?: string | null;
  /** acestep-1.5 text2music: the 5 Hz planner LM writes the metas, the caption and the song's audio codes first (true, as the platform's use_lm) */
  planner?: boolean | null;
  /** repaint: seconds; -1 or none: the recording's end; past it: the song extended to it */
  repaint_end?: number | null;
  /** repaint: how much of the recording is kept at the span's edges (balanced) */
  repaint_mode?: RepaintMode | null;
  /** repaint: seconds into the recording (0) */
  repaint_start?: number | null;
  /** repaint, balanced: 0 keeps the most, 1 the least (0.5) */
  repaint_strength?: number | null;
  /** edit: the words the recording sings now */
  source_lyrics?: string | null;
  /** acestep-1.5: text2music (default: from the words alone); with audio - cover (the recording performed anew: input its words, instructions its sound), repaint (repaint_start to repaint_end made again; an end past the recording extends it), edit (new words sung over the recording: source_lyrics the words it sings now), lego (a vocal track over an instrumental: acestep-1.5-base) */
  task?: AudioTask | null;
  /** acestep-1.5: beats a bar: "4", "3", "6" */
  time_signature?: string | null;
  /**
   * carry on from speech made here (a book in chunks): the file name (or url) of the chunk before; its last sentences (up to 15 s, cut at a pause) are the in-context reference, after the saved voice's sample when voice names one - pace and voice go on, anchored to the voice. Needs a model that clones (picked for you when model is not given); a built-in voice name is dropped
   * @maxLength 200
   */
  continue_from?: string | null;
  /** a recording of the voice to clone: WAV as base64 or a data: URL, or upload:<name> (audio.upload, any format it takes) - the Base model */
  ref_audio?: string | null;
  /** what the recording says: the closer, in-context clone (Breeze TTS 2: required, the exact transcript) */
  ref_text?: string | null;
  /**
   * several speakers (VibeVoice: input a script of "Speaker N: words" lines): each speaker's voice, Speaker 1's first - a saved voice's name, a recording (WAV, MP3, FLAC, Ogg, M4A as base64 or a data: URL) or upload:<name>, or {ref_audio | voice, ref_text}; a model that takes them is picked when model is not given
   * @maxItems 4
   */
  speakers?: unknown[] | null;
  /** a built-in voice (qwen3-tts-custom: serena, vivian, uncle_fu, ryan, aiden, ono_anna, sohee, eric, dylan; audio.info lists them) or a saved one (audio.voices.list: spoken by a model that clones). Checked when submitted, the model loaded or not: an unknown name is a 400 at once (the message lists the voices). /v1/audio/speech also takes OpenAI's names (alloy, ash, ballad, coral, echo, fable, nova, onyx, sage, shimmer, verse): built-in voices of qwen3-tts-custom (vivian, ryan, aiden, serena), or a model's own voice */
  voice?: string | null;
  /** other keys */
  [key: string]: unknown;
}

/** ACE-Step 1.5's task: text2music | cover | repaint | edit | lego */
export type AudioTask = "text2music" | "cover" | "repaint" | "edit" | "lego";

