/** A route's failure: the words its body's `error` said, and the body. */
export class RouteError extends Error {
  constructor(message: string, readonly body: unknown) {
    super(message);
  }
}

function runtime(base: string, fetcher: typeof fetch) {
  const words = (e: any): string => (typeof e === "string" ? e : (e?.message ?? JSON.stringify(e)));
  const read = async (res: Response, u: string, ownError: boolean): Promise<any> => {
    const text = await res.text();
    let v: any = null;
    try {
      v = text ? JSON.parse(text) : null;
    } catch {
      throw new RouteError(`${u}: the answer is not JSON (HTTP ${res.status})`, text);
    }
    const failed = v !== null && typeof v === "object" && !Array.isArray(v) && v.error != null && (!ownError || v.ok === false);
    if (failed) throw new RouteError(words(v.error), v);
    return v;
  };
  return {
    url(path: string, req: object, query: boolean): string {
      const fields = req as Record<string, unknown>;
      const used = new Set<string>();
      let p = path.replace(/\{([^}]+)\}/g, (_, k: string) => {
        used.add(k);
        return encodeURIComponent(String(fields[k] ?? ""));
      });
      if (query) {
        const q = new URLSearchParams();
        for (const [k, v] of Object.entries(fields)) {
          if (used.has(k) || v === undefined || v === null) continue;
          for (const x of Array.isArray(v) ? v : [v]) q.append(k, String(x));
        }
        const s = q.toString();
        if (s) p += `?${s}`;
      }
      return base + p.slice(1);
    },
    async json(method: string, u: string, body?: BodyInit, type?: string, ownError = false): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      return read(res, u, ownError);
    },
    async either(method: string, u: string, body: unknown, ownError = false): Promise<any> {
      const form = body instanceof FormData;
      const res = await fetcher(u, { method, body: form ? body : JSON.stringify(body), headers: form ? undefined : { "content-type": "application/json" } });
      return read(res, u, ownError);
    },
    async blob(method: string, u: string, body?: BodyInit, type?: string): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      if ((res.headers.get("content-type") ?? "").startsWith("application/json")) return read(res, u, false);
      return res.blob();
    },
  };
}

export function routes(base = "", fetcher: typeof fetch = (u, i) => fetch(u, i)) {
  const r = runtime(base, fetcher);
  return {
    /**
     * The card: its name, memory, power and temperatures
     * @route GET /api/gpu
     * @tags page
     */
    gpu: (): Promise<Gpu> => r.json("GET", r.url("/api/gpu", {}, true), undefined, undefined, false),
    /**
     * Whether the server answers
     * @route GET /health
     * @tags page
     */
    health: (): Promise<Health> => r.json("GET", r.url("/health", {}, true), undefined, undefined, false),
    /**
     * The model served, as OpenAI lists models
     * @route GET /v1/models
     * @alias /models
     * @tags openai
     */
    models: (): Promise<ModelList> => r.json("GET", r.url("/v1/models", {}, true), undefined, undefined, false),
    /**
     * The model and what it takes: its defaults, options, a speech engine's voices, a recogniser's languages
     * @route GET /api/info
     * @tags page
     */
    info: (): Promise<Info> => r.json("GET", r.url("/api/info", {}, true), undefined, undefined, false),
    /**
     * What the server is doing now (the page polls it)
     * @route GET /api/progress
     * @tags page
     */
    progress: (): Promise<Progress> => r.json("GET", r.url("/api/progress", {}, true), undefined, undefined, false),
    /**
     * The songs and speech made here, newest first (their settings from the WAVs)
     * @route GET /api/history
     * @tags page
     */
    history: (): Promise<History> => r.json("GET", r.url("/api/history", {}, true), undefined, undefined, false),
    /**
     * Stops a request: the one named (running or waiting), else the one running (between frames or steps)
     * @route POST /api/cancel
     * @tags page
     */
    cancel: (req: CancelReq = {}): Promise<Cancelled> => r.json("POST", r.url("/api/cancel", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A song or speech an answer links, whole or the byte range asked for (the player seeks)
     * @route GET /v1/audio/files/{name}
     * @tags files
     * @produces audio/wav
     * @ranges
     */
    file: (req: FileName): string => r.url("/v1/audio/files/{name}", req, true),
    /**
     * The saved voices (none without an output directory)
     * @route GET /api/voices
     * @tags voices
     */
    voices: (): Promise<Voices> => r.json("GET", r.url("/api/voices", {}, true), undefined, undefined, false),
    /**
     * A saved voice's sample
     * @route GET /v1/audio/voices/{name}
     * @tags voices
     * @produces audio/wav
     */
    voiceSample: (req: VoiceName): string => r.url("/v1/audio/voices/{name}", req, true),
    /**
     * Saves a voice: a recording sent, or a file made here (its text, description and language with it)
     * @route POST /api/voices/add
     * @tags voices
     */
    voiceAdd: (req: VoiceAdd): Promise<SavedVoice> => r.json("POST", r.url("/api/voices/add", req, false), JSON.stringify(req), "application/json", false),
    /**
     * Removes a saved voice
     * @route POST /api/voices/remove
     * @tags voices
     */
    voiceRemove: (req: VoiceRemove): Promise<VoiceRemoved> => r.json("POST", r.url("/api/voices/remove", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A recording written down (a recogniser: whisper): its text, language, timed stretches and words (JSON only, no multipart form)
     * @route POST /v1/audio/transcriptions
     * @alias /audio/transcriptions
     * @tags openai
     */
    transcriptions: (req: AudioTranscribeBody = {}): Promise<Transcript> => r.json("POST", r.url("/v1/audio/transcriptions", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A song or speech, as the model is (the reference server's speech endpoint, and OpenAI's): speech streamed (chunked, sent as each stretch of the text is spoken) in mp3 (the default), opus, aac, flac, wav or pcm (raw s16le, 24 kHz, mono); a song's WAV, or another of those formats streamed; with response_format url JSON with its link
     * @route POST /v1/audio/speech
     * @alias /audio/speech
     * @tags openai
     * @produces application/json, audio/mpeg, audio/ogg, audio/aac, audio/flac, audio/wav, audio/L16
     */
    speech: (req: AudioSpeechBody = {}): Promise<Sound | Blob> => r.blob("POST", r.url("/v1/audio/speech", req, false), JSON.stringify(req), "application/json"),
  };
}
